import{_ as a,o as n,c as i,a1 as s}from"./chunks/framework.DYnGRJP5.js";const u=JSON.parse('{"title":"Setup & Deployment Guide","description":"","frontmatter":{},"headers":[],"relativePath":"2ndbrain/setup-and-deployment.md","filePath":"2ndbrain/setup-and-deployment.md"}'),t={name:"2ndbrain/setup-and-deployment.md"};function o(l,e,r,p,d,h){return n(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="setup-deployment-guide" tabindex="-1">Setup &amp; Deployment Guide <a class="header-anchor" href="#setup-deployment-guide" aria-label="Permalink to &quot;Setup &amp; Deployment Guide&quot;">​</a></h1><p>This guide covers how to set up the Firebase services and Gemini AI required for <strong>2ndBrain</strong>, configure environment variables, and run the application locally.</p><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to &quot;1. Prerequisites&quot;">​</a></h2><p>You need accounts for the following services:</p><ul><li><strong>Firebase</strong> (Authentication &amp; Firestore)</li><li><strong>Google AI Studio</strong> (For the Gemini 2.5 Flash API Key)</li><li><strong>Node.js</strong> (v18+ recommended)</li></ul><h2 id="_2-firebase-configuration" tabindex="-1">2. Firebase Configuration <a class="header-anchor" href="#_2-firebase-configuration" aria-label="Permalink to &quot;2. Firebase Configuration&quot;">​</a></h2><p>2ndBrain relies entirely on Firebase for Authentication and Firestore database storage.</p><ol><li>Go to the <a href="https://console.firebase.google.com/" target="_blank" rel="noreferrer">Firebase Console</a> and create a new project.</li><li><strong>Enable Firestore Database</strong>: Create a database. Start in <em>Test Mode</em> for local development, but ensure you write proper security rules before deploying to production.</li><li><strong>Enable Authentication</strong>: Go to Authentication &gt; Sign-in method and enable the <strong>Google</strong> provider.</li><li><strong>Register Web App</strong>: Add a web app to your Firebase project to generate your configuration keys.</li></ol><h2 id="_3-gemini-api-configuration" tabindex="-1">3. Gemini API Configuration <a class="header-anchor" href="#_3-gemini-api-configuration" aria-label="Permalink to &quot;3. Gemini API Configuration&quot;">​</a></h2><p>To power the Neural Copilot, you need a Gemini API key.</p><ol><li>Go to <a href="https://aistudio.google.com/" target="_blank" rel="noreferrer">Google AI Studio</a>.</li><li>Click <strong>Get API key</strong> and create a new key.</li></ol><hr><h2 id="_4-environment-variables" tabindex="-1">4. Environment Variables <a class="header-anchor" href="#_4-environment-variables" aria-label="Permalink to &quot;4. Environment Variables&quot;">​</a></h2><p>Create a <code>.env</code> file in the root directory (<code>projects/second-brain/.env</code>) and populate it with the configuration keys:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Google AI Studio</span></span>
<span class="line"><span>VITE_GEMINI_API_KEY=your_gemini_api_key_here</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Firebase Configuration</span></span>
<span class="line"><span>VITE_FIREBASE_API_KEY=your_api_key</span></span>
<span class="line"><span>VITE_FIREBASE_AUTH_DOMAIN=your_project_id.firebaseapp.com</span></span>
<span class="line"><span>VITE_FIREBASE_PROJECT_ID=your_project_id</span></span>
<span class="line"><span>VITE_FIREBASE_STORAGE_BUCKET=your_project_id.appspot.com</span></span>
<span class="line"><span>VITE_FIREBASE_MESSAGING_SENDER_ID=your_sender_id</span></span>
<span class="line"><span>VITE_FIREBASE_APP_ID=your_app_id</span></span></code></pre></div><hr><h2 id="_5-running-locally" tabindex="-1">5. Running Locally <a class="header-anchor" href="#_5-running-locally" aria-label="Permalink to &quot;5. Running Locally&quot;">​</a></h2><p>Once your <code>.env</code> is configured and Firebase is set up:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Clone the repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yuvrajshrirame/second-brain.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> second-brain</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Start the Vite development server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Access the app at <code>http://localhost:5173</code>.</p><hr><h2 id="_6-building-deployment" tabindex="-1">6. Building &amp; Deployment <a class="header-anchor" href="#_6-building-deployment" aria-label="Permalink to &quot;6. Building &amp; Deployment&quot;">​</a></h2><p><strong>2ndBrain</strong> is a standard Vite React Single Page Application (SPA) and can be deployed to any static hosting service like Vercel, Netlify, or Firebase Hosting.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate the production build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Preview the production build locally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><h3 id="deployment-notes" tabindex="-1">Deployment Notes: <a class="header-anchor" href="#deployment-notes" aria-label="Permalink to &quot;Deployment Notes:&quot;">​</a></h3><ul><li>Ensure you add your <code>.env</code> variables (including the <code>VITE_GEMINI_API_KEY</code>) to your hosting provider&#39;s dashboard before building.</li><li>Configure your hosting provider to handle SPA Routing (rewrite all traffic to <code>index.html</code>).</li></ul>`,26)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
